sp_widget.css:
.row {
  display: grid;
  grid-template-columns: repeat(2, 1fr); /* 2 cards per row */
  gap: 20px;
}

.card-col {
  width: 100%; /* Grid controls the layout */
}

.card {
  /* Remove fixed height */
  /* height: 100%; */
  padding: 20px;
  border: 1px solid #edebeb;
  border-radius: 10px;
  box-shadow: rgba(99, 99, 99, 0.2) 0px 2px 8px 0px;
  box-sizing: border-box;
}

.card-body {
  /* Remove fixed height */
  /* height: 100%; */
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-sizing: border-box;
}

/* Make button fit within card */
.btn-primary {
  max-width: 100%; /* prevent overflow */
  box-sizing: border-box;
  white-space: normal; /* allow wrapping if button text is long */
  overflow-wrap: break-word;
}


.card-body h5 {
  font-size: 1.3em;
}
.row:before {
	content: none;
}

.card-img-top {
  width: 40px;      /* fixed width */
  height: 40px;     /* fixed height */
  object-fit: contain; /* keep aspect ratio, no stretching */
  display: inline-block;
  vertical-align: middle;
  margin-bottom: 10px; /* optional spacing */
}

sp_widget.script:
(function() {
    data.items = [];
    // Get category sys_id for "Employee Portal"
    var categoryName = "Employee";
    var categoryGR = new GlideRecord('sc_category');
    categoryGR.addQuery('title', categoryName);
    categoryGR.query();
    if (categoryGR.next()) {
        var categorySysId = categoryGR.sys_id;

        // Fetch all active catalog items in that category
        var itemGR = new GlideRecord('sc_cat_item');
        itemGR.addQuery('active', true);
        itemGR.addQuery('category', categorySysId);
        itemGR.orderBy('name');
        itemGR.query();

        while (itemGR.next()) {
            data.items.push({
                sys_id: itemGR.sys_id.toString(),
                name: itemGR.name.toString(),
                short_description: itemGR.short_description.toString(),
                picture: itemGR.icon.getDisplayValue()
            });
        }
    }
})();
